import 'dart:convert';

import 'data.dart';

class DeputizationsResponse {
	String? message;
	Data? data;

	DeputizationsResponse({this.message, this.data});

	factory DeputizationsResponse.from(Map<String, dynamic> data) {
		return DeputizationsResponse(
			message: data['message'] as String?,
			data: data['data'] == null
						? null
						: Data.(data['data'] as Map<String, dynamic>),
		);
	}



	Map<String, dynamic> () {
		return {
			'message': message,
			'data': data?.(),		};
	}

  /// `dart:convert`
  ///
  /// Parses the string and returns the resulting Json object as [DeputizationsResponse].
	factory DeputizationsResponse.fromJson(String data) {
		return DeputizationsResponse.from(json.decode(data) as Map<String, dynamic>);
	}
  /// `dart:convert`
  ///
  /// Converts [DeputizationsResponse] to a JSON string.
	String toJson() => json.encode(());
}
